	private static LmdbNativeDispatchLoop<Void, String> directLoop(SingletonSet target, AtomicInteger opens) {
		LmdbNativeCandidate<String> raw = LmdbNativeCandidate.of("irKernelDistinct",
				LmdbNativeCostQuote.streaming(LmdbNativeCostVector.point(Feature.SCANNED_ROW, 100D), 100D), () -> {
					opens.incrementAndGet();
					return "raw";
				});
		LmdbNativeCandidate<String> certified = LmdbNativeCandidate.of("certified",
				LmdbNativeCostQuote.streaming(LmdbNativeCostVector.point(Feature.SCANNED_ROW, 200D), 100D)
						.distinct(true),
				() -> {
					opens.incrementAndGet();
					return "certified";
				});
		LmdbNativeStrategy<Void, String> offer = LmdbNativeStrategy.of(LmdbNativeDecisionPoint.ROW, "fixture",
				ignored -> LmdbNativeAdmission.of(List.of(raw, certified)));
		return new LmdbNativeDispatchLoop<>(LmdbNativeDecisionPoint.ROW, List.of(offer), target);
	}

	@ParameterizedTest
	@ValueSource(strings = { " LIMIT 2", " OFFSET 1 LIMIT 1" })
	void aParsedTwoPatternJoinReachesTheSameDistinctDemandMismatch(String slice) throws Exception {
		SailRepository repository = new SailRepository(new LmdbStore(dataDir,
				new LmdbStoreConfig("spoc,posc,ospc").setNativeEvaluationEnabled(true)
						.setDirectAdjacencyEnabled(false)));
		try {
			try (SailRepositoryConnection connection = repository.getConnection()) {
				ValueFactory vf = connection.getValueFactory();
				IRI subject = vf.createIRI("urn:distinct-demand:subject");
				IRI predicate = vf.createIRI("urn:distinct-demand:p");
				connection.begin();
				for (int i = 0; i < INPUT_ROWS; i++) {
					connection.add(subject, predicate, vf.createIRI("urn:distinct-demand:object:" + i));
				}
				connection.add(subject, vf.createIRI("urn:distinct-demand:q"),
						vf.createIRI("urn:distinct-demand:marker"));
				connection.commit();
			}
			QueryMeasured bag = query(repository, "SELECT ?s" + JOIN);
			QueryMeasured full = query(repository, "SELECT DISTINCT ?s" + JOIN);
			QueryMeasured limited = query(repository, "SELECT DISTINCT ?s" + JOIN + slice);
			assertThat(bag.outputRows()).as("the two-pattern relation really has one hundred projected duplicates")
					.isEqualTo(INPUT_ROWS);
			assertThat(full.outputRows()).isEqualTo(1);
			assertThat(limited.outputRows()).isEqualTo(slice.contains("OFFSET") ? 0 : 1);
			assertThat(full.selected().features().expected(Feature.INTERPRETED_ROW)).isPositive();
			assertThat(limited.selected().features().expected(Feature.INTERPRETED_ROW))
					.as("parsed DISTINCT %s reaches nestedLoop, but the distinct-key budget does not bound its raw input",
							slice.trim())
					.isEqualTo(full.selected().features().expected(Feature.INTERPRETED_ROW));
		} finally {
			repository.shutDown();
		}
	}

	private record QueryMeasured(int outputRows, LmdbNativeDecisionRecord.Entry selected) {
	}

	private static QueryMeasured query(SailRepository repository, String sparql) {
		List<LmdbNativeDecisionRecord.Entry> selected = new ArrayList<>();
		LmdbNativeDispatchLoop.observeSelections((target, label, id, record) -> {
			if (record.point() == LmdbNativeDecisionPoint.ROW) {
				assertThat(id).isEqualTo(LmdbNativeAttemptMetrics.PATH_NESTED_LOOP);
				selected.add(record.entries().get(record.winner()));
			}
		});
		int rows = 0;
		try (SailRepositoryConnection connection = repository.getConnection()) {
			SailTupleQuery prepared = (SailTupleQuery) connection.prepareTupleQuery(sparql);
			prepared.setForcedLmdbExecutionStrategy(LmdbNativeAttemptMetrics.PATH_NESTED_LOOP);
			try (TupleQueryResult result = prepared.evaluate()) {
				while (result.hasNext()) {
					assertThat(result.next().getValue("s").stringValue()).isEqualTo("urn:distinct-demand:subject");
					rows++;
				}
			}
		} finally {
			LmdbNativeDispatchLoop.observeSelections(null);
		}
		assertThat(selected).as("parsed query must actually open the requested row candidate: %s", sparql).hasSize(1);
		return new QueryMeasured(rows, selected.get(0));
	}

	private record Measured(int inputRows, int outputRows, LmdbNativeCostQuote fullQuote,
			LmdbNativeDecisionRecord.Entry selected) {
	}

	private static Measured execute(boolean distinct, long offset, long limit) throws Exception {
		LmdbNativeRowDetachmentTest.FakeStoreSource source = new LmdbNativeRowDetachmentTest.FakeStoreSource();
		long repeatedKey = source.add(SimpleValueFactory.getInstance().createIRI("urn:distinct-demand:only-key"));
		LinkedHashMap<String, Integer> names = new LinkedHashMap<>();
		names.put("key", 0);
		NativeSlotLayout layout = new NativeSlotLayout(names, null);
		layout.freeze(List.of("key"));
		ValuesRow[] rows = new ValuesRow[INPUT_ROWS];
		for (int i = 0; i < rows.length; i++) {
			rows[i] = new ValuesRow(new int[] { 0 }, new long[] { repeatedKey });
		}
		AtomicInteger inputRows = new AtomicInteger();
		// This transparent, pinned filter counts real logical pulls. It never rejects or adds a row.
		SlotPlan plan = new FilterPlan(new ValuesPlan(rows), row -> {
			inputRows.incrementAndGet();
			return true;
		}, -1L);
		LmdbNativeEvaluationStrategy strategy = mock(LmdbNativeEvaluationStrategy.class);
		when(strategy.forcedExecutionStrategyName()).thenReturn(LmdbNativeAttemptMetrics.PATH_NESTED_LOOP);
		NativeRowsStep step = new NativeRowsStep(source, plan, layout, new int[] { 0 }, new String[] { "key" },
				distinct, new int[0], new boolean[0], offset, limit, false, strategy, null, null, Set.of(), null, null);
		LmdbNativeCostQuote fullQuote;
		RowState quotingRow = new RowState(source, layout, EmptyBindingSet.getInstance());
		try {
			fullQuote = LmdbNativeCostQuote.streaming(LmdbNativePlanExecutionProfile.profile(plan, quotingRow, 0L,
					LmdbNativePlanExecutionProfile.Mode.SEQUENTIAL), INPUT_ROWS);
		} finally {
			quotingRow.memoryScope.close();
		}
		List<LmdbNativeDecisionRecord.Entry> selected = new ArrayList<>();
		LmdbNativeDispatchLoop.observeSelections((target, label, id, record) -> {
			assertThat(id).isEqualTo(LmdbNativeAttemptMetrics.PATH_NESTED_LOOP);
			selected.add(record.entries().get(record.winner()));
		});
		int outputRows = 0;
		try (CloseableIteration<BindingSet> result = new NativeRowsIteration(step, source,
				EmptyBindingSet.getInstance())) {
			while (result.hasNext()) {
				assertThat(result.next().getValue("key")).isEqualTo(source.lazyValue(repeatedKey));
				outputRows++;
			}
		} finally {
			LmdbNativeDispatchLoop.observeSelections(null);
		}
		assertThat(selected).as("capture the quote of the candidate that actually opened").hasSize(1);
		assertThat(selected.get(0).features()).isNotNull();
		return new Measured(inputRows.get(), outputRows, fullQuote, selected.get(0));
	}
